import{_ as e,o as r,c as a,a2 as d}from"./chunks/framework.CDU0sSpB.js";const f=JSON.parse('{"title":"Glossary","description":"Shared explanations of Hearth product and engineering concepts.","frontmatter":{"title":"Glossary","description":"Shared explanations of Hearth product and engineering concepts.","outline":false},"headers":[],"relativePath":"en/reference/glossary.md","filePath":"en/reference/glossary.md","lastUpdated":1793863446000}'),n={name:"en/reference/glossary.md"};function o(i,t,s,c,l,p){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p class="lead">A word should mean the same thing in the documentation, the interface, and the implementation. These are the concepts Hearth uses most often, explained in user-facing language first.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Hearth</td><td>A single-user, self-hosted, long-running personal Agent OS</td></tr><tr><td>Task</td><td>A unit of work the user wants completed, verified, and recoverable</td></tr><tr><td>Work unit</td><td>A small authorized piece of a task that can run and be verified on its own</td></tr><tr><td>Execution record</td><td>The input, result, artifacts, and failure reason from one real attempt</td></tr><tr><td>Fact record</td><td>An append-only system record from which interfaces, reports, and notifications are rebuilt</td></tr><tr><td>Checkpoint</td><td>A recoverable state saved during long-running work</td></tr><tr><td>Snapshot</td><td>A copy of a workspace or data state used for recovery or comparison</td></tr><tr><td>Executor</td><td>A controlled capability that completes a kind of work, such as general reasoning, Codex, a browser, or desktop operation</td></tr><tr><td>Connector</td><td>An official interface to an external system such as email, calendar, or cloud storage</td></tr><tr><td>Authorization scope</td><td>The objects, time, and risk level within which an action is allowed</td></tr><tr><td>Approval</td><td>The user&#39;s confirmation of one specific external action</td></tr><tr><td>External effect</td><td>A real-world impact such as sending, writing, deleting, publishing, paying, or operating a device</td></tr><tr><td>Receipt</td><td>A verifiable result left after an external action happens</td></tr><tr><td>Reconciliation</td><td>Querying external state when a result is uncertain to determine whether an action happened</td></tr><tr><td>Artifact</td><td>A file, report, spreadsheet, link, or other deliverable produced by a task</td></tr><tr><td>Memory</td><td>Long-term or medium-term context with provenance, scope, and sensitivity</td></tr><tr><td>Method</td><td>A verified, reusable procedure or tool recipe</td></tr><tr><td>Evaluation</td><td>Judging capability with real tasks, baselines, verifiers, and cost metrics</td></tr><tr><td>Canary</td><td>Limited real use of a new method before wider adoption</td></tr><tr><td>Stop switch</td><td>An entry point for pausing tasks, devices, or all external actions during an incident</td></tr><tr><td>Verified completion</td><td>Real completion supported by artifacts, evidence, and necessary receipts</td></tr></tbody></table>',3)])])}const u=e(n,[["render",o]]);export{f as __pageData,u as default};
